	local function newMovementRecorder(playerContext, duelers, currentMap, cameraDirector, inputHook, replicateBinding)
		local trove = Trove.new("movement_recorder")
		local persistence = RecordingPersistence.new()
		local recorder = {
			_trove = trove,
			_playerContext = playerContext,
			_duelers = duelers,
			_currentMap = currentMap,
			_persistence = persistence,
			_cameraDirector = cameraDirector,
			_inputHook = inputHook
		}
		local idleState = { kind = "Idle" }
		recorder._state = idleState
		recorder._waypoints = nil
		recorder._lastRecording = nil
		recorder._aliveState = nil
		recorder._replicateBinding = replicateBinding
		recorder._roundActive = false
		recorder._pendingStart = nil
		recorder.recordingsChanged = persistence.reloaded
		setmetatable(recorder, MovementRecorder)
		recorder:_Initialize(trove, playerContext)
		return recorder
	end
