		local function runBypasses()
			local bypassState = getBypassState()
			if bypassState == "Loaded" then
				return true
			end
			if bypassState == "Loading" then
				repeat
					task.wait()
				until getBypassState() == "Loaded"
				return true
			end
			setBypassState("Loading")
			repeat
				task.wait()
			until game:IsLoaded()
			if not verifyGameScripts() then
				LocalPlayer4:Kick("Not all game files are what we expected.. wait for an update or try again!")
				return false
			end
			if not waitForGcTargets() then
				LocalPlayer4:Kick("Failed to run bypasses (1)")
				return false
			end
			if hookCameraData() then
