		local _sample_dt_mean = humanizer._sample_dt_mean
		local _gamma_shape = humanizer._gamma_shape
		local sampleTimes = table.create(1)
		local sampleTime = 0
		while sampleTime < totalMs do
			sampleTime = sampleTime + math.clamp(
				gammaSample(_rng, humanizer._gamma_shape, _sample_dt_mean / _gamma_shape),
				2,
