	local function filterNested(map, predicate)
		local result = {}
		local key = nil
		while true do
			local inner
			key, inner = map(nil, key)
			if key == nil then
				break
			end
			local bucket, innerKey
			while true do
				local _
				innerKey, _ = inner(nil, innerKey)
				if innerKey == nil then
					break
				end
				if predicate(key, innerKey) then
					if bucket == nil then
						bucket = {}
						result[key] = bucket
					end
					bucket[innerKey] = true
				end
			end
		end
		return result
	end
