			end
		end
		page:_setSelected(true)
		page._menu:FadeCanvasGroup(page._page, true, page._fadeState)
		page._tab.ActivePage = page
		if page._tab._openedOnce then
			page._openedOnce = true
			page:_maybeRealize()
			page.Opened:Fire(true)
