	local function openColorPopup(picker, trigger)
		local menu = picker._menu
		local newPopup = Popup.new
		local trove = picker._trove
		local popupOptions = {
			Trigger = trigger,
			Size = UDim2.fromOffset(300, 300),
			AutomaticSize = Enum.AutomaticSize.Y,
			CornerRadius = 13,
			FlatBackground = true,
			Glow = true,
			SlideDistance = 16,
			ParentEntry = picker._parentOverlay
		}

		function popupOptions.Place(trigger2)
			local position = trigger2.AbsolutePosition
			return position.X + 1, position.Y + 83
		end

		function popupOptions.OnToggle(open)
			if open then
				local panel = picker._panel
				if panel ~= nil then
					panel.Repaint(true)
				end
			end
		end

		local popup = newPopup(menu, trove, popupOptions)
		picker._popup = popup
		if menuStyle.Scale ~= 1 then
			local uiScale = Instance.new("UIScale")
			uiScale.Scale = menuStyle.Scale
			uiScale.Parent = popup.Root
		end
		local build = ColorPanel.build
		local panelOptions = {
			AlphaEnabled = picker.AlphaEnabled,
			Gradient = picker.Gradient,
			Animatable = picker.Animatable,
