			AnimationMode = picker.AnimationMode,
			AnimationSpeed = picker.AnimationSpeed
		}
		local breathingMin = picker.AnimationBreathingRange
		if breathingMin then
			breathingMin = picker.AnimationBreathingRange.Min
		end
		panelOptions.AnimationBreathingMin = breathingMin
		local breathingMax = picker.AnimationBreathingRange
		if breathingMax then
			breathingMax = picker.AnimationBreathingRange.Max
		end
		panelOptions.AnimationBreathingMax = breathingMax
		local callbacks = {}

		function callbacks.SetHSVA(hue, sat, val, alpha)
			picker.Hue = hue
			picker.Sat = sat
			picker.Val = val
			picker.Alpha = alpha
			picker:_applyState(false)
		end

		function callbacks.SetDragMode(mode)
			picker._dragMode = mode
			local dragging
			dragging = not (mode == nil)
			picker.Dragging = dragging
		end

		function callbacks.SelectStop(index)
			if not (picker.Mode == "Gradient" and #picker.Stops ~= 0) then
				return
			end
			picker.ActiveStopIndex = math.clamp(index, 1, #picker.Stops)
			local stop = getActiveStop(picker)
			if stop ~= nil then
				picker.Color = stop.Value
				local val, sat, hue
				hue, sat, val = stop.Value:ToHSV()
				picker.Hue = hue
				picker.Sat = sat
				picker.Val = val
			end
			picker:_applyState(true)
		end

		function callbacks.MoveActiveStop(time)
			local activeStop = getActiveStop(picker)
			local isEndpoint
			isEndpoint = picker.ActiveStopIndex == 1
			if not isEndpoint then
				isEndpoint = picker.ActiveStopIndex == #picker.Stops
			end
			if not (picker.Mode == "Gradient" and activeStop ~= nil and not isEndpoint) then
				return
			end
			activeStop.Time = math.clamp(time, 0, 1)
			picker.ActiveStopIndex = Stops.sort(picker.Stops, activeStop)
			picker:_applyState(false)
		end

		function callbacks.AddStop()
			if picker.Mode ~= "Gradient" then
				setPickerMode(picker, "Gradient")
			end
			local activeStop = getActiveStop(picker)
			local time = 0.5
			if activeStop ~= nil then
				if picker.ActiveStopIndex < #picker.Stops then
					time = (activeStop.Time + picker.Stops[picker.ActiveStopIndex + 1].Time) * 0.5
				elseif 1 < picker.ActiveStopIndex then
					time = (picker.Stops[picker.ActiveStopIndex - 1].Time + activeStop.Time) * 0.5
				end
			end
			local newStop = { Time = time, Value = picker.Color }
			table.insert(picker.Stops, newStop)
			picker.ActiveStopIndex = Stops.sort(picker.Stops, newStop)
			picker:_applyState(false)
		end

		function callbacks.RemoveStop()
			if not (picker.Mode == "Gradient" and not (#picker.Stops <= 2)) then
				return
			end
			local activeIndex = picker.ActiveStopIndex
			if activeIndex == 1 or activeIndex == #picker.Stops then
				return
			end
			local removedTime = picker.Stops[activeIndex].Time
			table.remove(picker.Stops, activeIndex)
			local nearestIndex = 1
			local nearestDistance = math.huge
			local stops = picker.Stops
			local index = nil
			while true do
				local stop
				index, stop = stops(nil, index)
				if index == nil then
					break
				end
				local distance = math.abs(stop.Time - removedTime)
				if distance < nearestDistance then
					nearestIndex = index
					nearestDistance = distance
				end
			end
			picker.ActiveStopIndex = nearestIndex
			picker._dragMode = nil
			picker.Dragging = false
			picker:_applyState(false)
		end

		function callbacks:SetMode()
			setPickerMode(picker, self)
			picker:_applyState(false)
		end

		function callbacks.SetAlpha(alpha)
			picker.Alpha = math.clamp(alpha, 0, 1)
			picker:_applyState(false)
		end

		function callbacks.SetRgb(rgb)
			local target = picker
			local set = target.Set
			local value = { Rgb = rgb, Alpha = picker.Alpha, Stops = picker.Value.Stops }
			set(target, value, false)
		end

		function callbacks:SetAnimationMode()
			picker:SetAnimationMode(self)
		end

		function callbacks:SetAnimationSpeed()
			picker:SetAnimationSpeed(self)
		end

		function callbacks:SetAnimationBreathingRange()
			picker:SetAnimationBreathingRange(self)
		end

		local builtPanel = build(menu, popup, picker, panelOptions, callbacks)
		picker._panel = builtPanel
		builtPanel.Repaint(true)
	end
