	local function setPickerValue(picker, value, silent)
		local rgb = value.Rgb
		if not rgb then
			rgb = picker.Color
		end
		local alpha = picker.Alpha
		if value.Alpha ~= nil then
			alpha = math.clamp(value.Alpha, 0, 1)
		end
		local stops = value.Stops
		local mode = picker.Mode
		if picker.Gradient == "off" then
			mode = "Solid"
			stops = nil
		elseif stops ~= nil then
			mode = 0 < #stops and "Gradient" or "Solid"
		end
		local val, sat, hue
		hue, sat, val = rgb:ToHSV()
		if mode == "Gradient" then
			local ensure = Stops.ensure
			if not stops then
				stops = picker.Stops
			end
			picker.Stops = ensure(stops, rgb)
			picker.ActiveStopIndex = math.clamp(picker.ActiveStopIndex, 1, #picker.Stops)
			local activeStop = getActiveStop(picker)
			if activeStop ~= nil then
				activeStop.Value = rgb
			end
		elseif not (stops == nil or not (0 < #stops)) then
			picker.Stops = Stops.ensure(stops, rgb)
		end
		if picker._dragMode == "sat" or picker._dragMode == "alpha" or not (0 < val and 0 < sat) then
			hue = picker.Hue
		end
		setPickerMode(picker, mode)
		picker.Hue = hue
		picker.Sat = sat
		picker.Val = val
		picker.Alpha = alpha
		picker:_applyState(silent)
	end
