		function ProjectileBreakerTeleport:_HasProjectileThreat()
			local enemies = self._fighters.enemies
			local index = nil
			while true do
				local enemy
				index, enemy = enemies(nil, index)
				if index == nil then
					break
				end
				local gun = enemy.itemObserver:EquippedItemAsGun()
