			ui.Dropdown.Visible = true
			local menu = self_._menu
			local tween = menu.Tween
			local dropdown = ui.Dropdown
			local goal = { Position = UDim2.fromOffset(x, y) }
			tween(menu, dropdown, goal)
		end
		self_._visible = true
		self_._menu:SetOverlayOpen(ui.Entry, true)
	end
