		function SearchPalette:_moveSelection(delta)
			local count = #self._scored
			if count == 0 then
				return
			end
			local next = self._selectedIndex + delta
			if not (next < 1) then
				count = count < next and 1 or next
			end
			self._selectedIndex = count
			self:_refreshHighlight()
		end
