				if visible then
					show = seenVisible
				else
					show = visible
				end
				if show then
					show = not afterDivider
				end
				separator.Visible = show
			end
			if visible then
				seenVisible = true
				if entry.isDivider == true then
					afterDivider = true
				else
					afterDivider = false
				end
			end
		end
	end
