	local function waitForChild_proto(parent, name, timeout)
		local function executor(resolve, reject)
			local child = parent:WaitForChild(name, timeout)
			if child then
				resolve(child)
			else
				string.format(
					"%s: timed out waiting for %s",
					tostring(parent:GetFullName()),
					tostring(name)
				)
				reject()
			end
		end

		return (Promise.new(executor))
	end
