	local function loadSoundPresets()
		local presets = table.create(2)
		local names = {}
		local urlByName = {}
		local index = nil
		while true do
			local preset
			index, preset = presets(nil, index)
			if index == nil then
				break
			end
			table.insert(names, preset.name)
			urlByName[preset.name] = preset.url
		end
		local SoundPresets = { Names = names, UrlByName = urlByName }
		return SoundPresets
	end
