	local function buildReplica_proto(self_, model)
		if not self_._visibilityHook:IsEntityReady() then
			return
		end
		self_:_ClearReplica()
		local buildTrove = self_._trove:Extend()
		self_._buildTrove = buildTrove
		local replica = buildTrove:Add(BodyReplica.new(self_._visibilityHook, self_:_ShouldShowReplica(), model))

		local function onReady(replicaModel)
			self_._replica = replica
			replica:SetVisible(self_:_ShouldShowReplica())
			self_.replicaModelChanged:Fire(replicaModel)
		end

		buildTrove:AddPromise(replica:InitializeAsync():andThen(onReady))
	end
