	local function onContextAdded_proto(self_, context, contextTrove)
		self_._innerContext = context
		self_._visibilityHook:SetContext(context)
		local fighterState = context.fighterState

		local function onDecorated(fighterState2, model)
			if fighterState2 ~= fighterState then
				return
			end
			self_:_BuildReplica(model)
		end

		contextTrove:Connect(self_._characterAppearances.decorated, onDecorated)

		local function onEntityAdded()
			local model = self_._characterAppearances:GetDecoratedModel(fighterState)
			if model ~= nil then
				self_:_BuildReplica(model)
			end
		end

		contextTrove:Connect(fighterState.entityAdded, onEntityAdded)

		local function onEntityRemoved()
			self_:_ClearReplica()
		end

		contextTrove:Connect(fighterState.entityRemoved, onEntityRemoved)

		local function onDied()
			self_:_ClearReplica()
		end

		contextTrove:Connect(fighterState.character.died, onDied)

		local function onEnvironmentChanged(...)
			local replica = self_._replica
			if replica ~= nil then
				replica:SetVisible(self_:_ShouldShowReplica())
			end
		end

		contextTrove:Connect(fighterState.environmentIDChanged, onEnvironmentChanged)
		local model2 = self_._characterAppearances:GetDecoratedModel(fighterState)
		if model2 ~= nil then
			self_:_BuildReplica(model2)
		end
	end
