	local function setBodyMode_proto(self_, mode)
		if self_._bodyMode == mode then
			return
		end
		self_._bodyMode = mode
		self_:_Initialize()
		local renderHook = self_._viewModelRenderHook
		local setActive = renderHook.SetActive
		local isNative
		isNative = mode == "Native"
		setActive(renderHook, isNative)
		if mode == "Replica" then
			self_._isReplicaVisible = true
			self_._visibilityHook:SetMode("Hidden")
		elseif mode == "Native" then
			self_._isReplicaVisible = false
			self_._visibilityHook:SetMode("Shown")
		else
			self_._isReplicaVisible = false
			self_._visibilityHook:SetMode("Default")
		end
		local replica = self_._replica
		if replica ~= nil then
			replica:SetVisible(self_:_ShouldShowReplica())
		end
	end
