	local function onContextRemoved_proto(self_)
		self_._innerContext = nil
		self_._bodyMode = "Default"
		self_._viewModelRenderHook:SetActive(false)
		self_._visibilityHook:RevertState()
		self_._visibilityHook:SetContext(nil)
		self_:_ClearReplica()
