		function AutoDuel:_TryAutoLoadout(context, duel)
			local settings = Config.data.Misc.AutoLoadout
			if not settings.Enabled then
				return
			end
			local mapName = duel:GetMapName()
			local loadout = settings.PerMap
			if loadout then
				loadout = not (mapName == nil)
			end
			loadout = loadout and settings.Loadouts[mapName] or
				settings.Loadouts.Default
			if loadout == nil or next(loadout) == nil then
				return
			end
			if not settings.MultipleLoadouts then
				local slots = loadout["1"]
				if slots == nil then
					return
				end
				local valid = true
				local slot = nil
				while true do
					local weaponName
					slot, weaponName = slots(nil, slot)
					if slot == nil then
						break
					end
					if weaponName == "Unselected" or isWeaponBanned(context, weaponName) then
						valid = false
						break
					end
				end
				if not valid then
					return
				end
				local function ignore()
				end
				context.loadoutPicker:PickLoadoutAsync(slots):catch(ignore)
				return
			end
			local picked = {}
			local slotIndex = 4
			while true do
				slotIndex = slotIndex + -1
				if not (1 <= slotIndex) then
					break
				end
				local slotWeapons = loadout[tostring(slotIndex)]
				if slotWeapons ~= nil then
					local index = nil
					while true do
						local weaponName2
						index, weaponName2 = slotWeapons(nil, index)
						if index == nil then
							break
						end
						if not (weaponName2 == "Unselected" or isWeaponBanned(context, weaponName2)) then
							picked[index] = weaponName2
						end
					end
				end
			end
			if picked[1] == nil or picked[2] == nil or (picked[3] == nil or picked[4] == nil) then
				return
			end
			local function ignore2()
			end
			context.loadoutPicker:PickLoadoutAsync(picked):catch(ignore2)
		end
