	local function loadSoundId()
		local SoundId = {}

		local function trim(text)
			local trimmed = text:match("^%s*(.-)%s*$")
			if not trimmed then
				trimmed = ""
			end
			return trimmed
		end

		function SoundId.normalize(value)
			if type(value) == "number" then
				return (string.format("rbxassetid://%s", tostring(value)))
			end
			if type(value) ~= "string" then
				return nil
			end
			local trimmed = trim(value)
			if trimmed == "" then
				return nil
			end
			local digits = trimmed:match("^(%d+)$")
			if digits == nil then
				return trimmed
			end
			return (string.format("rbxassetid://%s", tostring(digits)))
		end

		function SoundId.classify(id)
			if id:match("^rbxasset%w*://") ~= nil then
				return "Asset"
			end
			if id:match("^https?://") == nil then
				return "File"
			end
			return "Url"
		end

		return SoundId
	end
