			local addTextBox2 = customSoundsSection.AddTextBox
			local soundIDFileURLTextBoxOptions = { Label = "Sound ID / File / URL" }
			local soundIDFileURLTextBox = addTextBox2(customSoundsSection, soundIDFileURLTextBoxOptions)
			local addButton = customSoundsSection.AddButton
			local addButtonOptions = { Label = "Add" }

			function addButtonOptions.OnClick()
				if not customSounds:Add(nameTextBox.Value, soundIDFileURLTextBox.Value).ok then
					return
				end
				nameTextBox:Set("")
				soundIDFileURLTextBox:Set("")
			end

			addButton(customSoundsSection, addButtonOptions)
			local addDropdown = customSoundsSection.AddDropdown
			local savedDropdownOptions = { Label = "Saved", Options = customSounds:GetNames(), CloseOnSelect = true }
			local savedDropdown = addDropdown(customSoundsSection, savedDropdownOptions)

			local function onSoundsChanged(names)
				savedDropdown:SetOptions(names)
			end

			savedDropdown:Connect(customSounds.changed, onSoundsChanged)
			local addButton2 = customSoundsSection.AddButton
			local removeButtonOptions = { Label = "Remove" }

			function removeButtonOptions.OnClick()
				local name = savedDropdown.Value
				if type(name) ~= "string" then
					return
				end
				customSounds:Remove(name)
			end

			addButton2(customSoundsSection, removeButtonOptions)
		end
