	local function getDefensiveCFrame_proto(cframe, shieldState, fighterState, target)
		if shieldState == "Equipped" then
			return (CFrame.new(cframe.Position, target.Position))
		end
		if shieldState == "Unequipped" then
			return (CFrame.new(
				cframe.Position,
				cframe.Position + (cframe.Position - target.Position)
			))
