		function SoundEsp:_OnPlayed(sound)
			if sound.Volume <= 0 then
				return
			end
			local now = os.clock()
			local lastPlayed = self._lastPlayedAt[sound]
			if not (lastPlayed == nil or not (now - lastPlayed < replayCooldown)) then
				return
			end
			self._lastPlayedAt[sound] = now
			local part = getSoundPart(sound)
			if part == nil then
				return
			end
			local camera = Workspace.CurrentCamera
			if camera == nil then
				return
			end
			local distance = (camera.CFrame.Position - part.Position).Magnitude
			local maxDistance = sound.RollOffMaxDistance
			if 0 < maxDistance and maxDistance < distance then
				return
			end
			local settings = Config.data.SoundVisualizer
			if 0 < settings.MinVolume and sound.Volume < settings.MinVolume then
				return
			end
			local model = part:FindFirstAncestorOfClass("Model")
			if not self:_PassesSourceFilter(settings.Source, model) then
				return
			end
			local falloff
			falloff = 0 < maxDistance
			falloff = falloff and 1 - math.clamp(distance / maxDistance, 0, 1) or 1
			local loudness = math.clamp(sound.Volume * falloff, 0, 1)
			local baseDuration = minDuration
			local extraDuration = (maxDuration - minDuration) * loudness
			local footParts
			footParts = not (model == nil)
			footParts = footParts and getFootParts(model) or {}
			local typeSettings
			typeSettings = 0 < #footParts
			local soundType
			soundType = typeSettings and "Footsteps" or typeSettings
			if not soundType then
				soundType = "Other"
			end
			if not settings.Types[soundType] then
				return
			end
			typeSettings = typeSettings and settings.Footsteps or settings.Other
			local color = typeSettings.UseLoudnessColor
			color = color and loudnessColor(loudness) or typeSettings.Color
			self:_SpawnVisuals(typeSettings.Mode, part, footParts, color, baseDuration + extraDuration)
		end
