								function ColorStops.toSequence(keypoints)
									local sorted = ColorStops.clone(keypoints)
									if #sorted == 0 then
										return (ColorSequence.new(Color3.new(1, 1, 1)))
									end
									ColorStops.sort(sorted)
									local result = {}
									local first = sorted[1]
									local last = sorted[#sorted]
									if 0 < first.Time then
										table.insert(
											result,
											ColorSequenceKeypoint.new(0, first.Value)
										)
									end
									local index = nil
