								function Page:Open()
									if self._fadeState.tweening then
										return
									end
									local activePage = self._tab.ActivePage
									if activePage == self or
										not (activePage == nil or
											not activePage._fadeState.tweening) then
										return
									end
									self._menu:CloseOverlays(nil, true)
									if activePage ~= nil then
										activePage:_setSelected(false)
										self._menu:FadeCanvasGroup(
											activePage._page,
											false,
											activePage._fadeState
										)
										if activePage._pendingOpen then
											activePage._pendingOpen = false
										else
											activePage.Opened:Fire(false)
										end
									end
									self:_setSelected(true)
									self._menu:FadeCanvasGroup(self._page, true, self._fadeState)
									self._tab.ActivePage = self
									if self._tab._openedOnce then
										self._openedOnce = true
										self:_maybeRealize()
										self.Opened:Fire(true)
									else
										self._pendingOpen = true
									end
								end
