								function ThirdPerson:GetOffset(cameraCFrame)
									if not self._isEnabled then
										return nil
									end
									local context = self._playerContext.inner
									if context == nil then
										return nil
									end
									if context.fighterState.environmentID == nil or not isFirstPerson() then
										return nil
									end
									local settings = Config.data.ThirdPerson
									local offset = Vector3.new(
										settings.X,
										settings.Y,
										settings.Z
									)
									if settings.RayCheck then
										local origin = cameraCFrame.Position
										local hit = workspace:Raycast(
											origin,
											cameraCFrame:VectorToWorldSpace(offset),
											self._worldInclude:GetParams()
										)
										if hit ~= nil then
											offset = cameraCFrame:VectorToObjectSpace(hit.Position - origin)
											local distance = offset.Magnitude
											if 0.2 < distance then
												offset = offset.Unit * (distance - 0.2)
											end
										end
									end
									return offset
								end
