								function PlayerHit:_HandleHit(damage, partName, player)
									local config = settings.data.PlayerHit
									local sound = config.Sound
									local volume, soundName, isHead
									if sound.Enabled then
										isHead = partName == "Head"
										if isHead then
											soundName = sound.HeadName
										else
											soundName = isHead
										end
										if not soundName then
											soundName = sound.BodyName
										end
										local soundId = self._customSounds:GetSoundId(soundName)
										if soundId ~= nil then
											if isHead then
												volume = sound.HeadVolume
											else
												volume = isHead
											end
											if not volume then
												volume = sound.BodyVolume
