										name, displayName = getPlayerNames(player)
										local template = notification.Text
										local gsub = template.gsub
										local replacements = { NAME = name, DNAME = displayName, PART = partName }
										local message = gsub(template, "%%(%w+)%%", replacements)

										local function notify()
											local notifier = notifications.Get()
											local notify_ = notifier.Notify
											local format = notifications.Template
											local text = message
											local values = { DMG = formatDamage(damage) }
											notify_(notifier, format(text, values))
										end

										task.spawn(notify)
									end
									local hitFlash = config.HitFlash
									if hitFlash.Enabled then
										self._hitFlash:Play(hitFlash.Color, hitFlash.Duration)
									end
									local chams = config.Chams
									if chams.Enabled then
										local hitChams = ChamsEffect.new(
											player,
											chams.Color,
											chams.Transparency,
											chams.Duration,
											chams.Material
										)
										table.insert(self._chams, hitChams)
									end
								end
