											end
										end

										page.Opened:Connect(onOpened)
									end

									followPage(teamPage, "Team")
									followPage(enemyPage, "Enemy")
									buildFactionSections(teamPage, "Team")
									buildFactionSections(enemyPage, "Enemy")
								end
