									local configMap = {
										Key = table.create(4),
										Mode = table.create(4),
										Active = table.create(4),
										ShowInList = table.create(4),
										Invisible = table.create(4)
									}
									keybindOptions.ConfigMap = configMap
									local keybind = addKeybind(section, keybindOptions)
									local setFeatureEnabled = keybind.SetFeatureEnabled
									local enabled
									enabled = enabledToggle.Value == true
									setFeatureEnabled(keybind, enabled)

									local function onEnabledChanged(featureEnabled)
										local keybind2 = keybind
										local setFeatureEnabled2 = keybind2.SetFeatureEnabled
										local enabled2
										enabled2 = featureEnabled == true
										setFeatureEnabled2(keybind2, enabled2)
									end

									enabledToggle:Connect(enabledToggle.ValueChanged, onEnabledChanged)
								end
