									local function syncSkinChangerControls_proto()
										local weapon = getSelectedWeapon()
										if weapon == "All" then
											skinPicker:Set("Unselected", true)
											wrapPicker:Set("Unselected", true)
											charmPicker:Set("Unselected", true)
											finisherPicker:Set("Unselected", true)
											invertedToggle:Set(false, true)
											return
										end
										local selections = app.cosmetics:GetSkinChangerSelections(weapon)
										if selections == nil then
											skinPicker:Set("Unselected", true)
											wrapPicker:Set("Unselected", true)
											invertedToggle:Set(false, true)
											charmPicker:Set("Unselected", true)
											finisherPicker:Set("Unselected", true)
										else
											skinPicker:Set(
												toDisplayName(selections.skin),
												true
											)
											local wrap = selections.wrap
											if wrap == nil then
												wrapPicker:Set("Unselected", true)
												invertedToggle:Set(false, true)
											else
												wrapPicker:Set(toDisplayName(wrap.name), true)
												invertedToggle:Set(wrap.inverted, true)
											end
											charmPicker:Set(
												toDisplayName(selections.charm),
												true
											)
											finisherPicker:Set(
												toDisplayName(selections.finisher),
												true
											)
										end
									end
