								function ProjectileBreakerTeleport:_ScanBatch(suffix)
									local breaker = Config.data.Ragebot.Evasion.ProjectileBreaker
									local upMin = breaker.DepthUp.Min
									local upMax = breaker.DepthUp.Max
									local forwardMin = breaker.DepthForward.Min
									local scanned = breaker.DepthForward
									scanned = scanned.Max
									local forwardSum = forwardMin + scanned
									scanned = 0
									local upDepth = (upMin + upMax) * 0.5
									local forwardDepth = forwardSum * 0.5

									local function consider(part)
										if not (part:IsA("BasePart") and
											not self._processedParts[part]) then
											return
										end
										self._processedParts[part] = true
										scanned = scanned + 1
										local candidate = findSurface(part)
										if candidate == nil then
											return
										end
										if isPositionBlocked(surfaceCFrame(candidate, upDepth, forwardDepth).Position) then
											return
										end
										table.insert(self._pool, candidate)
									end

									for _, tagged in CollectionService:GetTagged("RaycastWhitelist" .. suffix) do
										if not isHazard(tagged) then
											consider(tagged)
											if scanLimit <= scanned or poolLimit <= #self._pool then
												return
											end
											for _, descendant in tagged:GetDescendants() do
												if not isHazard(descendant) then
													consider(descendant)
													if scanLimit <= scanned or poolLimit <= #self._pool then
														return
													end
												end
											end
										end
